        var html = """
<!doctype html><html lang="tr"><head><link rel='stylesheet' href='/r129-feedback.css?v=1'><script defer src='/r129-feedback.js?v=1'></script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#252b33"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="İNOKSKAR"><title>Garanti Sorgulama | @@NAME@@</title><meta name="description" content="İnokskar ürününüzün garanti durumunu seri numarası ve doğrulama koduyla güvenli şekilde sorgulayın."><link rel="stylesheet" href="/r95-warranty.css?v=r147-search-compact"><link rel="stylesheet" href="/r99-brand.css"><link rel="stylesheet" href="/r103-public.css"><link rel="stylesheet" href="/r123-professional.css"><script src="/r123-security.js" defer></script><link rel="stylesheet" href="/r13-interface.css?v=r22-clean"><link rel="stylesheet" href="/r13-pages.css?v=r148-warranty-buttons"><link rel="stylesheet" href="/r22-public-shell.css?v=r22-4"><link rel="stylesheet" href="/r22-layout-fixes.css?v=responsive-audit-2"><script src="/r13-pages.js?v=central-logo-4" defer></script></head><body class="warranty-public-body">
