    public static string Certificate(JsonObject warranty, JsonObject? settings = null)
    {
        string Value(string key) => E(warranty[key]?.ToString() is string text && text.Length > 0 ? text : "—");
        string Date(string key) => DateOnly.TryParseExact(warranty[key]?.ToString(), "yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out var date) ? date.ToString("dd.MM.yyyy") : "—";
        var components = new StringBuilder();
        foreach (var node in warranty["components"] as JsonArray ?? new JsonArray())
        {
            if (node is not JsonObject c) continue;
            var covered = c["covered"]?.GetValue<bool>() == true;
            components.Append($"<tr><td>{E(c["name"]?.ToString())}</td><td>{(covered ? "Garanti kapsamında" : "Kapsam dışında")}</td><td>{(covered ? E(c["months"]?.ToString()) + " ay" : "—")}</td><td>{E(c["note"]?.ToString())}</td></tr>");
        }
        var dated = Date("manufacturingDate") != "—";
        var coded = !string.IsNullOrWhiteSpace(warranty["verificationCode"]?.ToString());
        var html = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Garanti Belgesi | İNOKSKAR</title><link rel="stylesheet" href="/warranty-document.css?v=20261011-5"><script defer src="/warranty-print-vendor.js?v=20261011-5"></script><script defer src="/warranty-document.js?v=20261011-5"></script></head><body class="warranty-certificate-body"><main class="certificate-shell" data-serial="@@SERIAL@@" data-code="@@CODE@@">

<section class="certificate-controls" aria-label="Belge ve etiket yazdırma"><div class="certificate-navigation"><div class="certificate-tabs"><button type="button" data-print-panel="pdf" aria-controls="certificate-pdf-panel" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M7 8V3h10v5M7 16H4V9h16v7h-3M7 13h10v8H7z"/></svg>Garanti belgesi yazdır</button><button type="button" data-print-panel="thermal" aria-controls="certificate-thermal-panel" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M3 3h9l9 9-9 9-9-9z"/><circle cx="8" cy="8" r="1"/></svg>80 × 50 mm termal</button><button type="button" data-print-panel="thermal-wide" aria-controls="certificate-thermal-wide-panel" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M8 9h8M8 13h8"/></svg>100 × 50 mm termal</button></div><a class="certificate-back certificate-return" data-certificate-back href="/admin/warranties/list">← Geri dön</a></div>
<div class="certificate-panel" id="certificate-pdf-panel" hidden><article class="certificate" id="warranty-document" aria-label="Garanti belgesi">
<header class="certificate-head"><a class="certificate-brand" href="/" aria-label="İNOKSKAR ana sayfa"><img src="/inokskar-header-brand.png" alt="İNOKSKAR Soğutma ve Endüstriyel Mutfak"></a><div class="certificate-heading"><span>Ürün güvence belgesi</span><h1>Garanti Belgesi</h1><p>Seri no · @@SERIAL@@</p></div></header>
<section class="certificate-product"><span class="certificate-section-title">Ürün bilgileri</span><h2>@@PRODUCT@@</h2><p>Ürün kodu: @@PRODUCT_CODE@@</p></section>
<dl class="certificate-meta"><div><dt>Teslim edilen işletme</dt><dd>@@BUSINESS@@</dd></div><div><dt>Müşteri / yetkili</dt><dd>@@CUSTOMER@@</dd></div><div><dt>İmalat tarihi</dt><dd>@@MANUFACTURED@@</dd></div><div><dt>Teslim tarihi</dt><dd>@@DELIVERY@@</dd></div><div><dt>Garanti süresi</dt><dd>@@MONTHS@@ ay</dd></div><div><dt>Garanti bitiş tarihi</dt><dd>@@END@@</dd></div><div><dt>Fatura numarası</dt><dd>@@INVOICE@@</dd></div><div><dt>Teslim belgesi numarası</dt><dd>@@DELIVERY_DOC@@</dd></div><div><dt>Seri numarası</dt><dd>@@SERIAL@@</dd></div><div><dt>Garanti doğrulama kodu</dt><dd>@@CODE@@</dd></div></dl>
<h3>Garanti kapsamı ve bileşenler</h3><table><thead><tr><th>Bileşen</th><th>Kapsam</th><th>Süre</th><th>Açıklama</th></tr></thead><tbody>@@COMPONENTS@@</tbody></table>
<div class="certificate-note"><strong>Garanti / teslim notu</strong>@@NOTE@@</div>
<div class="certificate-signatures"><div>Firma yetkilisi · İmza / kaşe</div><div>Teslim alan · İmza</div></div>
