            ["@@PRODUCT@@"] = Value("productName"), ["@@PRODUCT_CODE@@"] = Value("productCode"),
            ["@@BUSINESS@@"] = Value("businessName"), ["@@CUSTOMER@@"] = Value("customerName"),
            ["@@MANUFACTURED@@"] = Date("manufacturingDate"), ["@@DELIVERY@@"] = Date("deliveryDate"),
            ["@@MONTHS@@"] = Value("warrantyMonths"), ["@@END@@"] = Date("warrantyEndDate"),
            ["@@INVOICE@@"] = Value("invoiceNumber"), ["@@DELIVERY_DOC@@"] = Value("deliveryDocumentNumber"),
            ["@@SERIAL@@"] = Value("serialNumber"), ["@@CODE@@"] = Value("verificationCode"),
            ["@@NOTE@@"] = Value("warrantyNote"), ["@@COMPONENTS@@"] = components.ToString(),
            ["@@COMPANY@@"] = E(settings?["name"]?.ToString() ?? "İNOKSKAR SOĞUTMA VE ENDÜSTRİYEL MUTFAK"),
            ["@@CONTACT@@"] = E(string.Join(" · ", new[]{ settings?["address"]?.ToString(), settings?["phone"]?.ToString(), settings?["email"]?.ToString() }.Where(x=>!string.IsNullOrWhiteSpace(x)))),
            ["@@ID@@"] = E(Uri.EscapeDataString(warranty["id"]?.ToString() ?? "")),
            ["@@THERMAL_NOTICE@@"] = !coded ? "Etiket yazdırmak için garanti kaydında doğrulama kodu oluşturun." : !dated ? "İmalat tarihi kayıtlı değil; etikette — olarak gösterilir. Gerçek tarihi garanti kaydından ekleyebilirsiniz." : "Ürün adı, imalat tarihi, seri numarası ve doğrulama kodu etiket üzerinde yer alır.",
            ["@@THERMAL_DISABLED@@"] = coded ? "" : "disabled"
        };
        return System.Text.RegularExpressions.Regex.Replace(html, "@@[A-Z_]+@@", match=>values.TryGetValue(match.Value,out var value)?value:match.Value);
